SELECT o_year, SUM(CASE WHEN nation='BRAZIL' THEN volume ELSE 0 END)/NULLIF(SUM(volume),0) AS mkt_share FROM (SELECT EXTRACT(YEAR FROM o.o_orderdate) AS o_year, l.l_extendedprice*(1-l.l_discount) AS volume, n2.n_name AS nation FROM tpch_part p JOIN tpch_lineitem l ON p.p_partkey=l.l_partkey JOIN tpch_supplier s ON s.s_suppkey=l.l_suppkey JOIN tpch_orders o ON o.o_orderkey=l.l_orderkey JOIN tpch_customer c ON c.c_custkey=o.o_custkey JOIN tpch_nation n1 ON c.c_nationkey=n1.n_nationkey JOIN tpch_region r ON n1.n_regionkey=r.r_regionkey JOIN tpch_nation n2 ON s.s_nationkey=n2.n_nationkey WHERE r.r_name='AMERICA' AND o.o_orderdate BETWEEN DATE '1995-01-01' AND DATE '1996-12-31' AND p.p_type='STANDARD STEEL') x GROUP BY o_year ORDER BY o_year;
